/**
 * Frozen contract for the rebuilt reports layer (`convex/reports/`).
 *
 * Both the Convex backend and the React frontend import metric names, statuses,
 * and result shapes from this module ONLY. Divergence between what the backend
 * materializes and what the UI reads is a compile error, not a blank dashboard.
 *
 * Design: docs/solutions/architecture/athena-reporting-read-optimized-redesign-2026-07-28.md
 * Plan:   docs/solutions/architecture/athena-reporting-read-optimized-implementation-plan-2026-07-28.md
 *
 * FROZEN after Wave 0. Slices escalate contract changes; they do not edit this file.
 */

export const REPORTS_FOLD_VERSION = 1 as const;
export const REPORTS_FINGERPRINT_VERSION = 1 as const;

export const REPORT_SOURCE_DOMAINS = [
  "pos",
  "storefront",
  "service",
  "payments",
  "inventory",
  "daily_close",
] as const;
export type ReportSourceDomain = (typeof REPORT_SOURCE_DOMAINS)[number];

export const REPORT_FACT_KINDS = [
  "sale",
  "refund",
  "void",
  "correction",
  "return",
  "payment",
  "payment_refund",
  "close_snapshot",
  "inventory_issue",
  "procurement_receipt",
] as const;
export type ReportFactKind = (typeof REPORT_FACT_KINDS)[number];

export const REPORT_DAY_STATUSES = [
  "open",
  "provisional",
  "reconciled",
  "amended",
] as const;
export type ReportDayStatus = (typeof REPORT_DAY_STATUSES)[number];

/**
 * Authoritative definition of "Today in progress" in reporting.
 *
 * Reporting follows the materialized day lifecycle, not a browser or server
 * clock: the current operating day remains `open` until rollover advances it.
 */
export function isReportingTodayInProgress(
  status: ReportDayStatus | null | undefined,
): boolean {
  return status === "open";
}

/**
 * Day-level metrics. One FIELD per metric — never one row per metric.
 * `grossProfitMinor` is null when any revenue lacks a cost basis; the
 * uncovered portion is reported honestly in `uncostedRevenueMinor`.
 */
export type ReportDayMetrics = {
  grossSalesMinor: number;
  netSalesMinor: number;
  refundsMinor: number;
  unitsSold: number;
  unitsReturned: number;
  uncostedRevenueMinor: number;
  grossProfitMinor: number | null;
  paymentsCollectedMinor: number;
  paymentsRefundedMinor: number;
  paymentAllocatedMinor: number;
};

export const REPORT_DAY_METRIC_KEYS = [
  "grossSalesMinor",
  "netSalesMinor",
  "refundsMinor",
  "unitsSold",
  "unitsReturned",
  "uncostedRevenueMinor",
  "grossProfitMinor",
  "paymentsCollectedMinor",
  "paymentsRefundedMinor",
  "paymentAllocatedMinor",
] as const satisfies readonly (keyof ReportDayMetrics)[];

/** SKU-day metrics — the subset of day metrics that attribute to a SKU. */
export type ReportSkuDayMetrics = {
  unitsSold: number;
  unitsReturned: number;
  grossSalesMinor: number;
  netSalesMinor: number;
  refundsMinor: number;
  uncostedRevenueMinor: number;
  grossProfitMinor: number | null;
};

export const REPORT_SKU_DAY_METRIC_KEYS = [
  "unitsSold",
  "unitsReturned",
  "grossSalesMinor",
  "netSalesMinor",
  "refundsMinor",
  "uncostedRevenueMinor",
  "grossProfitMinor",
] as const satisfies readonly (keyof ReportSkuDayMetrics)[];

export type ReportDayFlags = {
  mixedCurrency: boolean;
  hasUncostedRevenue: boolean;
  quarantinedFactCount: number;
};

// ---------------------------------------------------------------------------
// Fold interface (slice A implements; slices C and F call)
// ---------------------------------------------------------------------------

/** Projection of a reportFact document that the fold consumes. Pure data. */
export type FoldFact = {
  factId: string;
  sourceDomain: ReportSourceDomain;
  sourceId: string;
  lineId: string;
  factKind: ReportFactKind;
  occurredAt: number;
  recordedAt: number;
  currency: string;
  grossAmountMinor: number;
  netAmountMinor: number;
  taxAmountMinor: number;
  discountAmountMinor: number;
  quantity: number;
  productSkuId?: string;
  unitCostMinor?: number;
  quarantined: boolean;
};

export type CloseRef = {
  closeId: string;
  acceptedAt: number;
  closeNetSalesMinor: number;
};

export type SkuDayFoldResult = ReportSkuDayMetrics;

export type DayFoldResult = {
  day: ReportDayMetrics & {
    status: Exclude<ReportDayStatus, "open">;
    flags: ReportDayFlags;
    factCount: number;
    lastFactRecordedAt: number;
    closeVarianceMinor?: number;
    postCloseNetSalesDeltaMinor?: number;
  };
  /** Keyed by productSkuId. Only SKUs with activity appear. */
  skuDays: Map<string, SkuDayFoldResult>;
};

/** Signature slice A implements. Pure: no ctx, no db, deterministic. */
export type FoldDayFn = (
  storeCurrency: string,
  facts: readonly FoldFact[],
  close?: CloseRef,
) => DayFoldResult;

// ---------------------------------------------------------------------------
// Ingestion interface (slice B1 implements; B2 emitters and F reseed call)
// ---------------------------------------------------------------------------

/** One fact as emitted by a domain mutation. Identity is structural. */
export type NewReportFact = {
  sourceDomain: ReportSourceDomain;
  sourceId: string;
  /** Line discriminator within the source document; "" for header-level facts. */
  lineId: string;
  factKind: ReportFactKind;
  /** Business time — when the event happened (NOT sync/arrival time). */
  occurredAt: number;
  /**
   * Normally omitted — ingestion stamps arrival time itself. The reseed
   * walker passes business time here so re-derived historical facts don't
   * postdate their day's close and wrongly fold every reseeded day as
   * `amended`. Live emitters must NOT set this.
   */
  recordedAt?: number;
  currency: string;
  grossAmountMinor: number;
  netAmountMinor: number;
  taxAmountMinor: number;
  discountAmountMinor: number;
  quantity: number;
  productSkuId?: string;
  unitCostMinor?: number;
};

export type ReportSkuTransactionEvidence = {
  sourceDomain: "pos" | "storefront";
  sourceId: string;
  reference: string;
  occurredAt: number;
  status: string;
  quantity: number;
  netSalesMinor: number;
  costMinor: number | null;
  grossProfitMinor: number | null;
  hasRefunds: boolean;
  hasAdjustments: boolean;
};

// ---------------------------------------------------------------------------
// Period keys and rollups
// ---------------------------------------------------------------------------

/** Calendar period keys: "d:2026-07-28" | "w:2026-W31" | "m:2026-07". */
export type ReportPeriodKey = string;

export function dayPeriodKey(operatingDate: string): ReportPeriodKey {
  return `d:${operatingDate}`;
}

export function monthPeriodKey(operatingDate: string): ReportPeriodKey {
  return `m:${operatingDate.slice(0, 7)}`;
}

/** First operating date of the three-calendar-month window ending at anchor. */
export function trailingThreeMonthsStart(anchorDate: string): string {
  const anchor = new Date(`${anchorDate}T00:00:00.000Z`);
  return new Date(
    Date.UTC(anchor.getUTCFullYear(), anchor.getUTCMonth() - 2, 1),
  )
    .toISOString()
    .slice(0, 10);
}

/**
 * ISO-8601 week key for an operating-date label. Operating dates are calendar
 * labels, so UTC math over the label is correct by construction — no store
 * timezone enters here.
 */
export function weekPeriodKey(operatingDate: string): ReportPeriodKey {
  const d = new Date(`${operatingDate}T00:00:00.000Z`);
  // ISO week: Thursday of the current week determines the week-year.
  const day = d.getUTCDay() === 0 ? 7 : d.getUTCDay();
  d.setUTCDate(d.getUTCDate() + 4 - day);
  const yearStart = Date.UTC(d.getUTCFullYear(), 0, 1);
  const week = Math.ceil(((d.getTime() - yearStart) / 86_400_000 + 1) / 7);
  return `w:${d.getUTCFullYear()}-W${String(week).padStart(2, "0")}`;
}

export function periodKeysForOperatingDate(
  operatingDate: string,
): ReportPeriodKey[] {
  return [
    dayPeriodKey(operatingDate),
    weekPeriodKey(operatingDate),
    monthPeriodKey(operatingDate),
  ];
}

/** Convex indexes sort ascending; store negated measures for descending top-N. */
export function descendingSortKey(value: number): number {
  return -value;
}

/**
 * Canonical currency-code form used on every fact and day doc. Store config
 * carries codes in mixed case (dev stores have "ghs"); emitters, the fold's
 * store-currency argument, and reseed must ALL normalize through this one
 * helper — a raw comparison silently excludes every fact as foreign currency.
 */
export function normalizeCurrencyCode(currency: string | undefined): string {
  return (currency ?? "").trim().toUpperCase() || "GHS";
}

// ---------------------------------------------------------------------------
// Overview document (slice C materializes; the dashboard subscribes to it ONLY)
// ---------------------------------------------------------------------------

export type ReportPeriodSnapshot = ReportDayMetrics & {
  dayCount: number;
  /** Days in the period still open/provisional (numbers may move). */
  unsettledDayCount: number;
};

export type ReportTrendPoint = {
  operatingDate: string;
  netSalesMinor: number;
  status: ReportDayStatus;
  /** Optional while existing overview documents are refreshed by the sweeper. */
  unitsSold?: number;
};

export type ReportTrustSummary = {
  reconciledDays: number;
  provisionalDays: number;
  amendedDays: number;
  oldestUnreconciledDate?: string;
};

export type ReportOverviewData = {
  updatedAt: number;
  currency: string;
  today: ReportPeriodSnapshot;
  yesterday: ReportPeriodSnapshot;
  weekToDate: ReportPeriodSnapshot;
  priorWeek: ReportPeriodSnapshot;
  trailing30: ReportPeriodSnapshot;
  trailing3Months: ReportPeriodSnapshot;
  comparisons: {
    netSalesVsPriorWeekBp: number | null;
    unitsSoldVsPriorWeekBp: number | null;
  };
  /** Last 30 operating days, ascending — the dashboard chart reads this inline. */
  dailyTrend: ReportTrendPoint[];
  trust: ReportTrustSummary;
};

// ---------------------------------------------------------------------------
// Read-query result shapes (slice D implements; slice E consumes)
// ---------------------------------------------------------------------------

export type ReportDayRow = ReportDayMetrics & {
  operatingDate: string;
  status: ReportDayStatus;
  currency: string;
  flags: ReportDayFlags;
  factCount: number;
  closeVarianceMinor?: number;
  postCloseNetSalesDeltaMinor?: number;
};

/**
 * Enough to tell one SKU from another in a list.
 *
 * Resolved at read time from `productSku` (all fields denormalized there, so
 * one document read per row and no joins). The `sku` code is what actually
 * disambiguates: product names repeat — wigclub has 13 SKUs named "bottle
 * water" identical on every other attribute — while the code is present on
 * every SKU. `size` is carried when set (~86% of SKUs) as a human-readable
 * hint; colour and length are too sparse to be worth a lookup.
 *
 * Absent when the SKU document is gone — a reporting fact outlives its
 * subject, so the id remains the fallback rather than dropping the row.
 */
export type ReportSkuIdentity = {
  displayName: string;
  sku?: string;
  size?: string;
  /** Current catalog net price in the store's minor currency unit. */
  netPriceMinor: number;
  /** Current catalog unit cost in the store's minor currency unit, when set. */
  unitCostMinor?: number;
  /** Primary SKU image, when one is available. */
  imageUrl?: string;
  /**
   * Owning product, for linking out to the product detail page. Already on
   * the `productSku` document, so it costs no extra read.
   */
  productId?: string;
  quantityAvailable?: number;
};

export type ReportSkuPeriodRow = ReportSkuDayMetrics & {
  productSkuId: string;
  periodKey: ReportPeriodKey;
  identity?: ReportSkuIdentity;
};

export type ReportSkuSortBy = "revenue" | "units";

export type ReportSkuMixRow = {
  key: string;
  productSkuId?: string;
  label: string;
  unitsSold: number;
  shareBasisPoints: number;
  identity?: ReportSkuIdentity;
};

export type ReportSkuMixData = {
  rows: ReportSkuMixRow[];
  totalUnitsSold: number;
  skuCount: number;
};

export type ReportRangeStatus = "pending" | "completed" | "failed";

export type ReportRangeSummary = {
  requestKey: string;
  startDate: string;
  endDate: string;
  status: ReportRangeStatus;
  totals?: ReportDayMetrics & { dayCount: number; unsettledDayCount: number };
  topSkus?: ReportSkuPeriodRow[];
  failureReason?: string;
  computedAt?: number;
  expiresAt: number;
};

export const REPORT_RANGE_MAX_DAYS = 366 as const;
export const REPORT_RANGE_TTL_MS = 7 * 24 * 60 * 60 * 1000;
export const REPORT_SKU_PAGE_SIZE = 10 as const;
export const REPORT_RANGE_TOP_SKU_LIMIT = 100 as const;
